import{_ as t,o as e,c as a,aw as l}from"./chunks/framework.DLufY-ao.js";const m=JSON.parse('{"title":"Спринты","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/theory/agile/agile/sprint.md","filePath":"wiki/dev-commit/theory/agile/agile/sprint.md"}'),r={name:"wiki/dev-commit/theory/agile/agile/sprint.md"};function o(n,i,s,c,d,p){return e(),a("div",null,[...i[0]||(i[0]=[l('<h1 id="спринты" tabindex="-1">Спринты <a class="header-anchor" href="#спринты" aria-label="Permalink to &quot;Спринты&quot;">​</a></h1><h2 id="sprint" tabindex="-1">Sprint <a class="header-anchor" href="#sprint" aria-label="Permalink to &quot;Sprint&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Спринт</p><ul><li><strong>Спринт</strong> - короткая итерация, строго ограниченная по времени (обычно 2−4 недели). В это время минимизируется длительность совещаний, но увеличивается их частота. Благодаря этому контроль за выполнением становится более гибким, а разработчики быстрее реагируют на возникающие проблемы. Традиционное планирование отходит на второй план, его место занимает журнал спринтов</li><li>Спринт - участок времени за который разработчики выполняют фиксированый набор задач, оцененных на Planning Poker и на оценочной сессии. В конце спринта всегда должен быть работоспособный кусок продукта либо сам продукт, который можно показать заказчику</li></ul></div><ul><li><strong>Начало</strong>: после Planning Poker и Сессии оценки</li><li>Длина спринтов одинаковая и обычно выбираются кратными неделям: 1,2,4 недели</li><li>В рамках спринта задача меняется свои статусы. Изначально после оценки задчи попадают в статус TODO</li><li>По итогу спринта - продукт который можно показать клиенту. Каждый разработчки презентует те задачи, которые он сделал. Заказчик видим конкретный результат, вносит коррективы</li></ul>',4)])])}const h=t(r,[["render",o]]);export{m as __pageData,h as default};
